  ('daily_worker_hygiene_logs', '3eb1cb3a-f634-45e6-a9e6-89418a6a2c8b'::uuid, timestamptz '2026-10-12T11:53:40.897043+00:00', true),
  ('daily_worker_hygiene_logs', 'c1eca389-6c00-4333-a91d-a3b180e9d989'::uuid, timestamptz '2026-10-13T01:46:27+00:00', false),
  ('daily_worker_hygiene_logs', 'c88478a2-2213-4d21-8908-8b461e074eae'::uuid, timestamptz '2026-10-13T11:43:28.403163+00:00', true),
  ('daily_worker_hygiene_logs', '0e565e47-fbe2-4404-baaa-ba8a2064d3ad'::uuid, timestamptz '2026-10-14T11:45:43.967318+00:00', true)
), current_rows AS (
  SELECT 'daily_air_conditioning_equipment_logs'::text AS table_name, x.id, x.status, x.approved_at FROM public.daily_air_conditioning_equipment_logs x WHERE x.id IN (SELECT e.id FROM expected e WHERE e.table_name = 'daily_air_conditioning_equipment_logs')
  UNION ALL
  SELECT 'daily_cold_storage_hygiene_logs'::text AS table_name, x.id, x.status, x.approved_at FROM public.daily_cold_storage_hygiene_logs x WHERE x.id IN (SELECT e.id FROM expected e WHERE e.table_name = 'daily_cold_storage_hygiene_logs')
  UNION ALL
  SELECT 'daily_hygiene_logs'::text AS table_name, x.id, x.status, x.approved_at FROM public.daily_hygiene_logs x WHERE x.id IN (SELECT e.id FROM expected e WHERE e.table_name = 'daily_hygiene_logs')
  UNION ALL
  SELECT 'daily_illumination_logs'::text AS table_name, x.id, x.status, x.approved_at FROM public.daily_illumination_logs x WHERE x.id IN (SELECT e.id FROM expected e WHERE e.table_name = 'daily_illumination_logs')
  UNION ALL
  SELECT 'daily_manufacturing_equipment_logs'::text AS table_name, x.id, x.status, x.approved_at FROM public.daily_manufacturing_equipment_logs x WHERE x.id IN (SELECT e.id FROM expected e WHERE e.table_name = 'daily_manufacturing_equipment_logs')
  UNION ALL
  SELECT 'daily_material_receiving_inspection_logs'::text AS table_name, x.id, x.status, x.approved_at FROM public.daily_material_receiving_inspection_logs x WHERE x.id IN (SELECT e.id FROM expected e WHERE e.table_name = 'daily_material_receiving_inspection_logs')
  UNION ALL
  SELECT 'daily_process_control_bread_logs'::text AS table_name, x.id, x.status, x.approved_at FROM public.daily_process_control_bread_logs x WHERE x.id IN (SELECT e.id FROM expected e WHERE e.table_name = 'daily_process_control_bread_logs')
  UNION ALL
  SELECT 'daily_raw_thawing_logs'::text AS table_name, x.id, x.status, x.approved_at FROM public.daily_raw_thawing_logs x WHERE x.id IN (SELECT e.id FROM expected e WHERE e.table_name = 'daily_raw_thawing_logs')
  UNION ALL
  SELECT 'daily_sanitation_facility_logs'::text AS table_name, x.id, x.status, x.approved_at FROM public.daily_sanitation_facility_logs x WHERE x.id IN (SELECT e.id FROM expected e WHERE e.table_name = 'daily_sanitation_facility_logs')
  UNION ALL
  SELECT 'daily_temp_humidity_logs'::text AS table_name, x.id, x.status, x.approved_at FROM public.daily_temp_humidity_logs x WHERE x.id IN (SELECT e.id FROM expected e WHERE e.table_name = 'daily_temp_humidity_logs')
  UNION ALL
  SELECT 'daily_worker_hygiene_logs'::text AS table_name, x.id, x.status, x.approved_at FROM public.daily_worker_hygiene_logs x WHERE x.id IN (SELECT e.id FROM expected e WHERE e.table_name = 'daily_worker_hygiene_logs')
)
SELECT count(*) AS 대상,
       count(*) FILTER (WHERE c.status = 'approved' AND c.approved_at = e.approved_at) AS 일치,
       count(*) FILTER (WHERE e.changed) AS 변경분_대상,
       count(*) FILTER (WHERE e.changed AND c.status = 'approved' AND c.approved_at = e.approved_at) AS 변경분_일치,
       COALESCE(string_agg(e.table_name || ':' || e.id || ' 상태=' || COALESCE(c.status, '없음') || ' 현재=' || COALESCE(c.approved_at::text, '없음'), ' | ')
         FILTER (WHERE c.id IS NULL OR c.status IS DISTINCT FROM 'approved' OR c.approved_at IS DISTINCT FROM e.approved_at), '없음') AS 불일치
FROM expected e
LEFT JOIN current_rows c ON c.table_name = e.table_name AND c.id = e.id;
